solution:
.page {
  padding: 16px;
}

.toc {
  padding: 12px 16px;
  border: 1px solid #f97316;
  border-radius: 6px;
  background: #fed7aa;
}

.toc ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.post h1 {
  margin: 0 0 12px;
}

.post p {
  margin: 0 0 12px;
  line-height: 1.5;
}

/* ---- Solution ---- */
.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 24px;
  align-items: start;
}

.toc {
  position: sticky;
  top: 16px;
}

@media (max-width: 600px) {
  .page {
    grid-template-columns: 1fr;
  }

  .toc {
    position: static;
  }
}
